mapper.select:
select AGENT_INSTITUTION_CODE agentInstitutionCode, AGENT_INSTITUTION_NAME agentInstitutionName, ISSUE_PARTY_ID issuePartyId, STATUS status, FILE_NO fileNo, ENCLOSURE_CHANGE_FLAG enclosureChangeFlag, ENCLOSURE_NUM enclosureNum, REMARK remark from CHB_AGENT_INSTITUTION_INFO where 1=1
and STATUS = #{status,jdbcType=VARCHAR}
and AGENT_INSTITUTION_CODE like concat(concat('%',#{agentInstitutionCode,jdbcType=VARCHAR}),'%')

select REGIST_BANK_CODE from CHB_ORG_REGIST_BANK_CODE
where
ORG_CODE = #{orgCode,jdbcType=VARCHAR}

mapper.update:
update CHB_AGENT_INSTITUTION_INFO
set ENCLOSURE_ADDRESS = #{enclosureAddress,jdbcType=VARCHAR},
ENCLOSURE_NUM = #{enclosureNum,jdbcType=VARCHAR},
FILE_NO = #{fileNo,jdbcType=VARCHAR}


        AGENT_INSTITUTION_CODE = #{agentInstitutionCode}

mapper.select:
select path from sys_upload_file_info sufi where exists (
select 1 from CHB_AGENT_INSTITUTION_INFO cpds where
sufi.seq_no = cpds.file_no

    and cpds.AGENT_INSTITUTION_CODE = #{agentInstitutionCode}

) limit 1
